mapper.select:
SELECT tc.train_car_cd,tc.train_car_number,s.seat_cd,s.seat_number,s.seat_column
FROM M_TrainCar AS tc
INNER JOIN M_SeatType AS st ON tc.seat_type_cd=st.seat_type_cd AND tc.train_car_cd=#{train_car_cd}
INNER JOIN M_Seat AS s ON st.seat_type_cd=s.seat_type_cd
ORDER BY s.seat_number,s.seat_column;
